1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.beans.factory.annotation.Autowired;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.controller.CityRegionResolver;
10	import org.springframework.samples.petclinic.rest.controller.TelephoneNormalizer;
11	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
12	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
13	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
14	import org.springframework.samples.petclinic.service.ClinicService;
15	import org.springframework.samples.petclinic.util.HashUtils;
16	import org.springframework.samples.petclinic.util.IdentityUtils;
17	
18	import java.time.LocalDate;
19	import java.time.Month;
20	import java.time.Period;
21	import java.util.Collection;
22	import java.util.List;
23	import java.util.Locale;
24	import java.util.OptionalInt;
25	
26	/**
27	 * Maps Owner & OwnerDto using Mapstruct
28	 */
29	@Mapper(uses = PetMapper.class)
30	public abstract class OwnerMapper {
31	
32	    /** Used to count the members of an owner's household when deriving derived fields. */
33	    @Autowired
34	    protected ClinicService clinicService;
35	
36	    /** Single source of truth for the city-to-region mapping behind an owner's locality. */
37	    @Autowired
38	    protected CityRegionResolver cityRegionResolver;
39	
40	    /** Formats the stored E.164 telephone into its human-readable display form. */
41	    @Autowired
42	    protected TelephoneNormalizer telephoneNormalizer;
43	
44	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
45	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
46	    @Mapping(target = "displayName",
47	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
48	    @Mapping(target = "initials", expression = "java(initials(owner))")
49	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
50	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
51	    @Mapping(target = "locality", expression = "java(locality(owner))")
52	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
53	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
54	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneNormalizer.toDisplayForm(owner.getTelephone()))")
55	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
56	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
57	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
58	    @Mapping(target = "ownerSegment", expression = "java(ownerSegment(owner))")
59	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
60	    public abstract OwnerDto toOwnerDto(Owner owner);
61	
62	    /**
63	     * The owner's self link: '/api/owners/' followed by the owner's id, or null when the
64	     * owner has no id assigned yet.
65	     */
66	    String selfLink(Owner owner) {
67	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
68	    }
69	
70	    /**
71	     * The fiscal year (starting 1 July) that {@code date} falls in, identified by the
72	     * calendar year in which the fiscal year ends: a date in July–December belongs to the
73	     * fiscal year ending the following calendar year, while January–June belongs to the one
74	     * ending that same calendar year.
75	     */
76	    public static int fiscalYear(LocalDate date) {
77	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
78	    }
79	
80	    /**
81	     * The owner's fiscal year formatted 'FY<YY>', where YY is the last two digits of the
82	     * fiscal year of the (business-day-adjusted) {@code registrationDate} and the fiscal year
83	     * starts on 1 July. Returns null when no registrationDate has been assigned.
84	     */
85	    String fiscalYear(Owner owner) {
86	        LocalDate registrationDate = owner.getRegistrationDate();
87	        if (registrationDate == null) {
88	            return null;
89	        }
90	        return String.format("FY%02d", fiscalYear(registrationDate) % 100);
91	    }
92	
93	    /**
94	     * The owner's age band derived from {@code birthDate} relative to the
95	     * {@code registrationDate}: 'MINOR' when under 18, 'ADULT' from 18 to 64
96	     * inclusive and 'SENIOR' at 65 or older. Returns null when either date is
97	     * absent so no band can be computed.
98	     */
99	    OwnerDto.AgeBandEnum ageBand(Owner owner) {
100	        LocalDate birthDate = owner.getBirthDate();
101	        LocalDate registrationDate = owner.getRegistrationDate();
102	        if (birthDate == null || registrationDate == null) {
103	            return null;
104	        }
105	        int age = Period.between(birthDate, registrationDate).getYears();
106	        if (age < 18) {
107	            return OwnerDto.AgeBandEnum.MINOR;
108	        }
109	        if (age < 65) {
110	            return OwnerDto.AgeBandEnum.ADULT;
111	        }
112	        return OwnerDto.AgeBandEnum.SENIOR;
113	    }
114	
115	    /**
116	     * The owner's check digit: a single Luhn check digit (0-9) computed over the digits
117	     * contained in the customerCode, or null when no customerCode has been assigned.
118	     */
119	    Integer checkDigit(Owner owner) {
120	        String customerCode = owner.getCustomerCode();
121	        return customerCode == null ? null : luhn(customerCode);
122	    }
123	
124	    /**
125	     * The Luhn check digit (0-9) over the digits contained in {@code s}: from the rightmost
126	     * digit leftward, every second digit is doubled (the rightmost first) with digits over 9
127	     * reduced by 9, and the check digit makes the total a multiple of ten.
128	     *
129	     * <p>This is the single Luhn derivation behind the application's identity values; like
130	     * {@link #fiscalYear(LocalDate)} and {@link #identityKey(Owner)} it is exposed so the check
131	     * digit is computed the one way wherever an identifier is assembled, including outside this
132	     * package.
133	     */
134	    public static int luhn(String s) {
135	        int sum = 0;
136	        boolean doubling = true;
137	        for (int i = s.length() - 1; i >= 0; i--) {
138	            char c = s.charAt(i);
139	            if (c < '0' || c > '9') {
140	                continue;
141	            }
142	            int d = c - '0';
143	            if (doubling) {
144	                d *= 2;
145	                if (d > 9) {
146	                    d -= 9;
147	                }
148	            }
149	            sum += d;
150	            doubling = !doubling;
151	        }
152	        return (10 - (sum % 10)) % 10;
153	    }
154	
155	    /**
156	     * The owner's derived identity key: the SHA-256 hex digest of the normalized telephone,
157	     * the lower-cased email (or an empty string when absent) and the {@link IdentityUtils#soundex
158	     * soundex} of the last name, joined by '|'. This single key is the sole basis for duplicate
159	     * detection on create — two owners are duplicates only when their whole identityKey matches,
160	     * so two people sharing a household (a like-sounding last name and postcode) but carrying
161	     * different telephones derive different keys and are all permitted.
162	     */
163	    public static String identityKey(Owner owner) {
164	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
165	        String email = owner.getEmail() == null ? "" : owner.getEmail().toLowerCase(Locale.ROOT);
166	        String lastNameSoundex = IdentityUtils.soundex(owner.getLastName());
167	        return HashUtils.sha256Hex(telephone + "|" + email + "|" + lastNameSoundex);
168	    }
169	
170	    /**
171	     * The owner's preferred contact channel: 'EMAIL' when an email address is
172	     * present, otherwise 'PHONE'.
173	     */
174	    String contactPreference(Owner owner) {
175	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
176	        return hasEmail ? "EMAIL" : "PHONE";
177	    }
178	
179	    /**
180	     * The REGION segment carried by the owner's assigned identity code: the part before the first
181	     * '-' of the {@code '<REGION>-<HASH8>'} customerCode. Returns null when no customerCode has been
182	     * assigned, or when it carries no region segment. This is the single place that reads the region
183	     * back out of the stored identifier, so every rule keyed on that region reads it the one way.
184	     */
185	    private String identityRegion(Owner owner) {
186	        String customerCode = owner.getCustomerCode();
187	        if (customerCode == null) {
188	            return null;
189	        }
190	        int dash = customerCode.indexOf('-');
191	        return dash >= 0 ? customerCode.substring(0, dash) : null;
192	    }
193	
194	    /**
195	     * The owner's locality: the REGION segment of its assigned identity code (see
196	     * {@link #identityRegion}). When no code has been assigned this falls back to the canonical
197	     * region derived from the owner via {@link CityRegionResolver}, preferring the postcode over the
198	     * city, or 'UNKNOWN' when neither yields a known region.
199	     */
200	    String locality(Owner owner) {
201	        String region = identityRegion(owner);
202	        return region != null ? region : cityRegionResolver.regionFor(owner.getCity(), owner.getPostcode());
203	    }
204	
205	    /**
206	     * The owner's segment, formatted '&lt;TIER&gt;_&lt;AREA&gt;'. TIER is 'PREMIUM' when the owner's
207	     * {@link #membershipLevel(Owner) membershipLevel} is 3 or more, otherwise 'STANDARD'. AREA is
208	     * 'METRO' when the owner's {@link #locality(Owner) locality} is a known region (NSW, VIC or QLD),
209	     * otherwise 'REGIONAL'.
210	     */
211	    OwnerDto.OwnerSegmentEnum ownerSegment(Owner owner) {
212	        String tier = membershipLevel(owner) >= 3 ? "PREMIUM" : "STANDARD";
213	        boolean knownRegion = cityRegionResolver.timezoneForRegion(locality(owner)) != null;
214	        String area = knownRegion ? "METRO" : "REGIONAL";
215	        return OwnerDto.OwnerSegmentEnum.fromValue(tier + "_" + area);
216	    }
217	
218	    /**
219	     * The owner's IANA timezone name derived from the owner's {@link #locality(Owner) locality}
220	     * via the fixed region-to-timezone table (NSW -> Australia/Sydney, VIC -> Australia/Melbourne,
221	     * QLD -> Australia/Brisbane). Returns null when the locality is not a region in the table.
222	     */
223	    String timezone(Owner owner) {
224	        return cityRegionResolver.timezoneForRegion(locality(owner));
225	    }
226	
227	    /**
228	     * The owner's membership points: starting at 0, plus 2 when an email address is present,
229	     * plus 1 when namesakeCount is 0, plus 2 for a household of 3 or more members, plus 3 when
230	     * the owner's tenure is more than one fiscal year.
231	     */
232	    public int membershipPoints(Owner owner) {
233	        int points = 0;
234	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
235	        if (hasEmail) {
236	            points += 2;
237	        }
238	        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
239	        if (uniqueName) {
240	            points += 1;
241	        }
242	        if (householdSize(owner) >= 3) {
243	            points += 2;
244	        }
245	        LocalDate registrationDate = owner.getRegistrationDate();
246	        boolean tenured = registrationDate != null
247	            && fiscalYear(LocalDate.now()) - fiscalYear(registrationDate) > 1;
248	        if (tenured) {
249	            points += 3;
250	        }
251	        return points;
252	    }
253	
254	    /**
255	     * The owner's numeric membership level from 1 to 4, derived from {@link #membershipPoints}
256	     * via {@link #levelForPoints} and then held to the household level-ceiling by
257	     * {@link #cappedByHousehold}.
258	     */
259	    public int membershipLevel(Owner owner) {
260	        return cappedByHousehold(owner, levelForPoints(membershipPoints(owner)));
261	    }
262	
263	    /**
264	     * Hold {@code level} to the household level-ceiling: an owner's membershipLevel may not exceed
265	     * one above the current maximum membershipLevel among the household members that already
266	     * existed when this owner registered — the other, non-deleted owners sharing its householdId
267	     * that were created earlier (a strictly lower id, ids being monotonic). When no such earlier
268	     * household member exists no ceiling applies and {@code level} is returned unchanged.
269	     *
270	     * @param owner the owner whose own level is being capped
271	     * @param level the owner's uncapped membership level
272	     * @return the level, capped at one above the earlier household members' maximum
273	     */
274	    private int cappedByHousehold(Owner owner, int level) {
275	        Integer id = owner.getId();
276	        String householdId = owner.getHouseholdId();
277	        if (id == null || householdId == null) {
278	            return level;
279	        }
280	        OptionalInt maxExisting = clinicService.findAllOwners().stream()
281	            .filter(existing -> !existing.isDeleted())
282	            .filter(existing -> existing.getId() != null && existing.getId() < id)
283	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
284	            .mapToInt(this::membershipLevel)
285	            .max();
286	        return maxExisting.isEmpty() ? level : Math.min(level, maxExisting.getAsInt() + 1);
287	    }
288	
289	    /**
290	     * The numeric membership level from 1 to 4 that {@code points} maps to: level 1 for 0-1
291	     * points, level 2 for 2-3 points, level 3 for 4-5 points and level 4 for 6 or more points.
292	     */
293	    int levelForPoints(int points) {
294	        if (points >= 6) {
295	            return 4;
296	        }
297	        if (points >= 4) {
298	            return 3;
299	        }
300	        if (points >= 2) {
301	            return 2;
302	        }
303	        return 1;
304	    }
305	
306	    /**
307	     * The owners belonging to {@code owner}'s household, i.e. those sharing its householdId
308	     * (including the owner itself once persisted). Returns an empty list when the owner has no
309	     * household id assigned.
310	     */
311	    List<Owner> householdMembers(Owner owner) {
312	        String householdId = owner.getHouseholdId();
313	        if (householdId == null) {
314	            return List.of();
315	        }
316	        return clinicService.findAllOwners().stream()
317	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
318	            .toList();
319	    }
320	
321	    /**
322	     * The number of owners belonging to {@code owner}'s household, i.e. those sharing its
323	     * householdId (including the owner itself once persisted). Returns 0 when the owner has no
324	     * household id assigned.
325	     */
326	    int householdSize(Owner owner) {
327	        return householdMembers(owner).size();
328	    }
329	
330	    /**
331	     * The owner's salutation: the {@code title} and last name separated by a single space
332	     * (e.g. 'DR who'), or just the last name when no title has been supplied.
333	     */
334	    String salutation(Owner owner) {
335	        String title = owner.getTitle();
336	        if (title == null || title.isBlank()) {
337	            return owner.getLastName();
338	        }
339	        return title + " " + owner.getLastName();
340	    }
341	
342	    /**
343	     * The upper-cased first letters of firstName and lastName, dot-separated with a
344	     * trailing dot, e.g. 'J.S.'.
345	     */
346	    String initials(Owner owner) {
347	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
348	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
349	    }
350	
351	    public abstract Owner toOwner(OwnerDto ownerDto);
352	
353	    @Mapping(target = "id", ignore = true)
354	    @Mapping(target = "pets", ignore = true)
355	    public abstract Owner toOwner(OwnerFieldsDto ownerDto);
356	
357	    public abstract List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
358	
359	    public abstract Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
360	
361	    public OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
362	        OwnerPageDto ownerPageDto = new OwnerPageDto();
363	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
364	        ownerPageDto.setPage(ownerPage.getNumber());
365	        ownerPageDto.setSize(ownerPage.getSize());
366	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
367	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
368	        return ownerPageDto;
369	    }
370	}
