     * the request. No owner is persisted unless every rule passes.
     *
     * @param ownerFieldsDto the submitted owner fields
     * @return the create outcome as an HTTP response
     */
    public ResponseEntity<OwnerDto> register(OwnerFieldsDto ownerFieldsDto) {
        return register(ownerFieldsDto, null);
    }

    /**
     * As {@link #register(OwnerFieldsDto)}, but honouring an optional {@code Idempotency-Key}.
     * When {@code idempotencyKey} is non-blank and a create with that key has already succeeded,
     * the owner it originally produced is returned with {@code 200 OK} instead of creating a
     * duplicate. Otherwise the normal create pipeline runs and, on success, the key is recorded
     * against the created owner so a later repeat resolves to the same owner.
     *
     * @param ownerFieldsDto the submitted owner fields
     * @param idempotencyKey the request's {@code Idempotency-Key} header, or {@code null} when absent
     * @return the create outcome as an HTTP response
     */
    public ResponseEntity<OwnerDto> register(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
        String key = (idempotencyKey == null || idempotencyKey.isBlank()) ? null : idempotencyKey.trim();
        if (key != null) {
            Integer existingId = idempotencyKeys.get(key);
            if (existingId != null) {
                Owner original = this.clinicService.findOwnerById(existingId);
                if (original != null) {
                    return new ResponseEntity<>(ownerMapper.toOwnerDto(original), HttpStatus.OK);
                }
                // The originally created owner is gone; forget the stale key and create afresh.
                idempotencyKeys.remove(key);
            }
        }
        HttpHeaders headers = new HttpHeaders();
        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
        if (owner.getRegistrationDate() == null) {
            owner.setRegistrationDate(LocalDate.now());
        }
        // A supplied registration date may not be later than the server's current date.
        if (owner.getRegistrationDate().isAfter(LocalDate.now())) {
            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
        }
        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
        LocalDate registrationDate = owner.getRegistrationDate();
        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
            .map(Owner::getRegistrationDate)
            .filter(registrationDate::equals)
            .count();
        if (ownersCreatedThatDay >= 100) {
            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
        }
        String address = normalizedAddress(owner);
        if (address == null) {
            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
        }
        owner.setAddress(address);
        String telephone = telephoneNormalizer.normalize(owner.getTelephone());
        if (telephone == null) {
            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
        }
        if (!telephoneNormalizer.hasValidNationalNumberLength(telephone)) {
            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
        }
        owner.setTelephone(telephone);
        String email = owner.getEmail();
        if (email != null) {
            email = email.trim();
            if (!EMAIL_PATTERN.matcher(email).matches()) {
                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
            }
            String domain = email.substring(email.indexOf('@') + 1).toLowerCase(Locale.ROOT);
            if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
            }
            owner.setEmail(email.toLowerCase(Locale.ROOT));
        }
        // A postcode is optional, but when supplied it must be four digits and valid for the
        // owner's city per the fixed region table; a city with no known region accepts any
        // 4-digit postcode. Reject an out-of-range or malformed postcode with 400.
        String postcode = owner.getPostcode();
        if (postcode != null) {
            if (!POSTCODE_PATTERN.matcher(postcode).matches()
                    || !cityRegionResolver.isPostcodeValidForCity(owner.getCity(), postcode)) {
                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
            }
        }
        // The owner's telephone and email are now in their canonical, stored form.
        // The household id is deterministic: owners with the same normalized last name and
        // postcode share it automatically. Assign it unconditionally so the membership-level
        // ceiling can key off it; it no longer participates in duplicate detection, which now
        // rests solely on the identity key below.
        owner.setHouseholdId(householdResolver.householdId(owner));
        // Duplicate detection is the single identity key: a candidate is rejected only when its
        // whole identityKey (normalized telephone, lower-cased email and soundex of the last name)
        // collides with a non-deleted owner's. Two people sharing a household with different
        // telephones therefore derive different keys and are both admitted; the second is instead
        // flagged as a possible duplicate by the soft-match rule below.
        if (isDuplicateOwner(owner)) {
            return new ResponseEntity<>(HttpStatus.CONFLICT);
        }
        String cityKey = IdentityUtils.normalizeIdentity(owner.getCity());
        long ownersInCity = this.clinicService.findAllOwners().stream()
            .filter(existing -> IdentityUtils.normalizeIdentity(existing.getCity()).equals(cityKey))
            .count();
        if (ownersInCity >= 50) {
            return new ResponseEntity<>(HttpStatus.CONFLICT);
        }
        // Approaching-capacity warning: the city already holds 40-49 owners (the hard limit is 50,
        // rejected above). ownersInCity counts the existing owners the candidate is joining.
        owner.setCapacityWarning(ownersInCity >= 40 && ownersInCity < 50);
        owner.setMemberId(memberId(owner));
        owner.setNamesakeCount(namesakeCount(owner));
        owner.setBulkSignupWarning(ownersCreatedThatDay > 80);
        // Soft-match: the candidate has already cleared the hard-duplicate check, but its
        // identityKey may still differ from an existing owner's while their last names sound alike
        // (equal soundex) and their postcodes match — a likely re-registration of the same person
        // under a different telephone or email. When it does, it is created but flagged as a
        // possible duplicate of that existing owner; otherwise the flag is false and no reference
        // is recorded.
        Integer possibleDuplicateOf = possibleDuplicateOf(owner);
        owner.setPossibleDuplicate(possibleDuplicateOf != null);
        owner.setPossibleDuplicateOf(possibleDuplicateOf);
        this.clinicService.saveOwner(owner);
        if (key != null) {
            idempotencyKeys.put(key, owner.getId());
        }
        ownerAuditor.ownerCreated(owner, ownerMapper.membershipLevel(owner));
        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
        headers.setLocation(UriComponentsBuilder.newInstance()
            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
    }

    /**
     * The owner's postal address in the single canonical form under which it is stored, or
     * {@code null} when the owner supplies no usable address. An owner may supply its address
     * in EITHER form: the structured {@code addressLine1} (with an optional {@code addressLine2})
     * is preferred, and the flat {@code address} remains accepted for backward compatibility.
     *
     * <p>Normalization by {@link AddressNormalizer} is applied to whichever fields are supplied.
     * When a non-blank {@code addressLine1} is present the owner's structured fields are replaced
     * with their normalized values (a blank or absent {@code addressLine2} is cleared to
     * {@code null}) and the returned address is composed as the normalized {@code addressLine1},
     * with a single space and the normalized {@code addressLine2} appended when present. Otherwise
     * the flat {@code address} is normalized and the structured fields are cleared. A blank result
     * (no usable address in either form) has no canonical form and is reported as {@code null} so
     * the caller can reject the request with 400.
     *
     * <p>This is the single point at which an owner's address is resolved and normalized on
     * create, so every rule keyed on the stored address reads the one value produced here.
     *
     * @param owner the owner about to be created
     * @return the canonical stored address, or {@code null} when the owner supplies none
     */
    private String normalizedAddress(Owner owner) {
        String rawLine1 = owner.getAddressLine1();
        if (rawLine1 != null && !rawLine1.isBlank()) {
            String line1 = addressNormalizer.normalize(rawLine1);
            String line2 = addressNormalizer.normalize(owner.getAddressLine2());
            owner.setAddressLine1(line1);
            owner.setAddressLine2(line2.isBlank() ? null : line2);
            return line2.isBlank() ? line1 : line1 + " " + line2;
        }
        owner.setAddressLine1(null);
        owner.setAddressLine2(null);
        String address = addressNormalizer.normalize(owner.getAddress());
        return address.isBlank() ? null : address;
    }

    /**
     * Whether {@code candidate} collides with an already-registered owner under the single
     * identity rule enforced on create. This is the one point at which a new owner is
     * rejected as a duplicate (HTTP 409): all duplicate detection is consolidated into the
     * derived {@link OwnerMapper#identityKey identityKey} — the SHA-256 hex over the normalized
     * telephone, the lower-cased email (or an empty string when absent) and the soundex of the
     * last name, joined by '|'. The candidate clashes only when its WHOLE identityKey equals an
     * existing owner's; because the telephone is part of the key, two people sharing a household
     * (a like-sounding last name and postcode) with different telephones have different
     * identityKeys and are both allowed.
     *
     * <p>The candidate arrives with its telephone and email already normalized, and each existing
     * owner is stored in the same canonical form, so an identityKey match means the two owners are
     * genuinely the same identity.
     *
     * @param candidate the fully-normalized owner about to be created
     * @return {@code true} if an existing owner already occupies the candidate's identityKey
     */
    private boolean isDuplicateOwner(Owner candidate) {
        String identityKey = OwnerMapper.identityKey(candidate);
        return this.clinicService.findAllOwners().stream()
            .filter(existing -> !existing.isDeleted())
            .map(OwnerMapper::identityKey)
            .anyMatch(identityKey::equals);
    }

    /**
     * The id of the existing owner the fully-normalized {@code candidate} soft-matches, or
     * {@code null} when there is none. A soft match is an owner whose whole identityKey differs
     * from the candidate's (so it is not a hard duplicate) yet whose last name sounds alike (equal
     * {@link IdentityUtils#soundex soundex}) and whose postcode matches — a likely re-registration
     * of the same person under a different telephone or email. Both must supply a postcode for a
     * match to be possible; when several existing owners qualify the lowest id is returned so the
     * result is deterministic.
     *
     * @param candidate the fully-normalized owner about to be created
     * @return the matching existing owner's id, or {@code null} if the candidate is no soft match
     */
    private Integer possibleDuplicateOf(Owner candidate) {
        String postcode = candidate.getPostcode();
        if (postcode == null || postcode.isBlank()) {
            return null;
        }
        String identityKey = OwnerMapper.identityKey(candidate);
        String lastNameSoundex = IdentityUtils.soundex(candidate.getLastName());
        return this.clinicService.findAllOwners().stream()
            .filter(existing -> !existing.isDeleted()
                && !identityKey.equals(OwnerMapper.identityKey(existing))
                && IdentityUtils.soundex(existing.getLastName()).equals(lastNameSoundex)
                && postcode.equals(existing.getPostcode()))
            .map(Owner::getId)
            .filter(java.util.Objects::nonNull)
            .min(Integer::compareTo)
            .orElse(null);
    }

    /**
     * Build the member id assigned to {@code owner} on create, formatted
     * {@code '<REGION><FY><HASH8><CHK>'}: REGION is the region code derived from the owner's
     * postcode (falling back to the city) via {@link CityRegionResolver}, FY is the two-digit
     * fiscal year of the (business-day-adjusted) registrationDate (the fiscal year starts on
     * 1 July), HASH8 is the first eight upper-case hex characters of the SHA-256 digest of the
     * normalized telephone concatenated with the last name (the same HASH8 used by the
     * region-and-hash identity), and CHK is a single Luhn check digit computed over the digits
     * of {@code '<REGION><FY><HASH8>'} (e.g. 'NSW261A2B3C4D5').
     *
     * <p>When the computed id collides with an already-registered owner's memberId it is
     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that
     * makes it unique (e.g. 'NSW261A2B3C4D5-2'), and the unique id is returned.
     */
    private String memberId(Owner owner) {
        String region = cityRegionResolver.regionFor(owner.getCity(), owner.getPostcode());
        String fy = String.format("%02d", OwnerMapper.fiscalYear(owner.getRegistrationDate()) % 100);
        String hash8 = HashUtils.sha256HexPrefix(owner.getTelephone() + owner.getLastName(), 8);
        String core = region + fy + hash8;
        String base = core + OwnerMapper.luhn(core);
        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
            .map(Owner::getMemberId)
            .filter(java.util.Objects::nonNull)
            .collect(java.util.stream.Collectors.toSet());
        return disambiguate(base, existing);
    }

    /**
     * Make {@code base} unique among the {@code existing} identity codes: return it unchanged when
     * it is free, otherwise append {@code '-<n>'} with the smallest {@code n} of 2 or more that is
     * not already taken (e.g. 'NSW-1A2B3C4D-2'). This is the single de-duplication step an assigned
     * identity code passes through, so a collision is broken the one way wherever a code is built.
     */
    private static String disambiguate(String base, java.util.Set<String> existing) {
        if (!existing.contains(base)) {
            return base;
        }
        int n = 2;
        while (existing.contains(base + "-" + n)) {
            n++;
        }
        return base + "-" + n;
    }

    /**
     * The number of existing owners that share {@code owner}'s firstName and lastName,
     * compared case-insensitively. The candidate is not yet stored at the point this is
     * assigned, so it does not count itself. This is the value stored as the owner's
     * namesakeCount on create.
     */
    private int namesakeCount(Owner owner) {
        return (int) this.clinicService.findAllOwners().stream()
            .filter(existing -> owner.getFirstName().equalsIgnoreCase(existing.getFirstName())
                && owner.getLastName().equalsIgnoreCase(existing.getLastName()))
            .count();
    }

    /** Fixed list of public holidays that a registration date must roll past. */
    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
        LocalDate.of(2026, 1, 1),
        LocalDate.of(2026, 1, 26),
        LocalDate.of(2026, 4, 25),
        LocalDate.of(2026, 12, 25),
        LocalDate.of(2026, 12, 28));

    /**
     * Roll a registration date forward to the next business day: a Saturday, Sunday
     * or listed public holiday advances one day at a time until it lands on a weekday
     * that is not a public holiday. A plain weekday is returned unchanged.
     */
    private static LocalDate toBusinessDay(LocalDate date) {
        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
            date = date.plusDays(1);
        }
        return date;
    }

    private static boolean isWeekend(LocalDate date) {
        return switch (date.getDayOfWeek()) {
            case SATURDAY, SUNDAY -> true;
            default -> false;
        };
    }
}

package org.springframework.samples.petclinic.mapper;

import org.jspecify.annotations.NonNull;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.data.domain.Page;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.controller.CityRegionResolver;
import org.springframework.samples.petclinic.rest.controller.TelephoneNormalizer;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
import org.springframework.samples.petclinic.service.ClinicService;
import org.springframework.samples.petclinic.util.HashUtils;
import org.springframework.samples.petclinic.util.IdentityUtils;

import java.time.LocalDate;
import java.time.Month;
import java.time.Period;
import java.util.Collection;
import java.util.List;
import java.util.Locale;
import java.util.OptionalInt;

/**
 * Maps Owner & OwnerDto using Mapstruct
 */
@Mapper(uses = PetMapper.class)
public abstract class OwnerMapper {

    /** Used to count the members of an owner's household when deriving derived fields. */
    @Autowired
    protected ClinicService clinicService;

    /** Single source of truth for the city-to-region mapping behind an owner's locality. */
    @Autowired
    protected CityRegionResolver cityRegionResolver;

    /** Formats the stored E.164 telephone into its human-readable display form. */
    @Autowired
    protected TelephoneNormalizer telephoneNormalizer;

    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
    @Mapping(target = "salutation", expression = "java(salutation(owner))")
    @Mapping(target = "displayName",
        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
    @Mapping(target = "initials", expression = "java(initials(owner))")
    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
    @Mapping(target = "locality", expression = "java(locality(owner))")
    @Mapping(target = "timezone", expression = "java(timezone(owner))")
    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
    @Mapping(target = "telephoneDisplay", expression = "java(telephoneNormalizer.toDisplayForm(owner.getTelephone()))")
    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
    @Mapping(target = "ownerSegment", expression = "java(ownerSegment(owner))")
    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
    public abstract OwnerDto toOwnerDto(Owner owner);

    /**
     * The owner's self link: '/api/owners/' followed by the owner's id, or null when the
     * owner has no id assigned yet.
     */
    String selfLink(Owner owner) {
        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
    }

    /**
     * The fiscal year (starting 1 July) that {@code date} falls in, identified by the
     * calendar year in which the fiscal year ends: a date in July–December belongs to the
     * fiscal year ending the following calendar year, while January–June belongs to the one
     * ending that same calendar year.
     */
    public static int fiscalYear(LocalDate date) {
        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
    }

    /**
     * The owner's fiscal year formatted 'FY<YY>', where YY is the last two digits of the
     * fiscal year of the (business-day-adjusted) {@code registrationDate} and the fiscal year
     * starts on 1 July. Returns null when no registrationDate has been assigned.
     */
    String fiscalYear(Owner owner) {
        LocalDate registrationDate = owner.getRegistrationDate();
        if (registrationDate == null) {
            return null;
        }
        return String.format("FY%02d", fiscalYear(registrationDate) % 100);
    }

    /**
     * The owner's age band derived from {@code birthDate} relative to the
     * {@code registrationDate}: 'MINOR' when under 18, 'ADULT' from 18 to 64
     * inclusive and 'SENIOR' at 65 or older. Returns null when either date is
     * absent so no band can be computed.
     */
    OwnerDto.AgeBandEnum ageBand(Owner owner) {
        LocalDate birthDate = owner.getBirthDate();
        LocalDate registrationDate = owner.getRegistrationDate();
        if (birthDate == null || registrationDate == null) {
            return null;
        }
        int age = Period.between(birthDate, registrationDate).getYears();
        if (age < 18) {
            return OwnerDto.AgeBandEnum.MINOR;
        }
        if (age < 65) {
            return OwnerDto.AgeBandEnum.ADULT;
        }
        return OwnerDto.AgeBandEnum.SENIOR;
    }

    /**
     * The owner's check digit: a single Luhn check digit (0-9) computed over the digits
     * contained in the customerCode, or null when no customerCode has been assigned.
     */
    Integer checkDigit(Owner owner) {
        String customerCode = owner.getCustomerCode();
        return customerCode == null ? null : luhn(customerCode);
    }

    /**
     * The Luhn check digit (0-9) over the digits contained in {@code s}: from the rightmost
     * digit leftward, every second digit is doubled (the rightmost first) with digits over 9
     * reduced by 9, and the check digit makes the total a multiple of ten.
     *
     * <p>This is the single Luhn derivation behind the application's identity values; like
     * {@link #fiscalYear(LocalDate)} and {@link #identityKey(Owner)} it is exposed so the check
     * digit is computed the one way wherever an identifier is assembled, including outside this
     * package.
     */
    public static int luhn(String s) {
        int sum = 0;
        boolean doubling = true;
        for (int i = s.length() - 1; i >= 0; i--) {
            char c = s.charAt(i);
            if (c < '0' || c > '9') {
                continue;
            }
            int d = c - '0';
            if (doubling) {
                d *= 2;
                if (d > 9) {
                    d -= 9;
                }
            }
            sum += d;
            doubling = !doubling;
        }
        return (10 - (sum % 10)) % 10;
    }

    /**
     * The owner's derived identity key: the SHA-256 hex digest of the normalized telephone,
     * the lower-cased email (or an empty string when absent) and the {@link IdentityUtils#soundex
     * soundex} of the last name, joined by '|'. This single key is the sole basis for duplicate
     * detection on create — two owners are duplicates only when their whole identityKey matches,
     * so two people sharing a household (a like-sounding last name and postcode) but carrying
     * different telephones derive different keys and are all permitted.
     */
    public static String identityKey(Owner owner) {
        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
        String email = owner.getEmail() == null ? "" : owner.getEmail().toLowerCase(Locale.ROOT);
        String lastNameSoundex = IdentityUtils.soundex(owner.getLastName());
        return HashUtils.sha256Hex(telephone + "|" + email + "|" + lastNameSoundex);
    }

    /**
     * The owner's preferred contact channel: 'EMAIL' when an email address is
     * present, otherwise 'PHONE'.
     */
    String contactPreference(Owner owner) {
        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
        return hasEmail ? "EMAIL" : "PHONE";
    }

    /**
     * The REGION segment carried by the owner's assigned identity code: the part before the first
     * '-' of the {@code '<REGION>-<HASH8>'} customerCode. Returns null when no customerCode has been
     * assigned, or when it carries no region segment. This is the single place that reads the region
     * back out of the stored identifier, so every rule keyed on that region reads it the one way.
     */
    private String identityRegion(Owner owner) {
        String customerCode = owner.getCustomerCode();
        if (customerCode == null) {
            return null;
        }
        int dash = customerCode.indexOf('-');
        return dash >= 0 ? customerCode.substring(0, dash) : null;
    }

    /**
     * The owner's locality: the REGION segment of its assigned identity code (see
     * {@link #identityRegion}). When no code has been assigned this falls back to the canonical
     * region derived from the owner via {@link CityRegionResolver}, preferring the postcode over the
     * city, or 'UNKNOWN' when neither yields a known region.
     */
    String locality(Owner owner) {
        String region = identityRegion(owner);
        return region != null ? region : cityRegionResolver.regionFor(owner.getCity(), owner.getPostcode());
    }

    /**
     * The owner's segment, formatted '&lt;TIER&gt;_&lt;AREA&gt;'. TIER is 'PREMIUM' when the owner's
     * {@link #membershipLevel(Owner) membershipLevel} is 3 or more, otherwise 'STANDARD'. AREA is
     * 'METRO' when the owner's {@link #locality(Owner) locality} is a known region (NSW, VIC or QLD),
     * otherwise 'REGIONAL'.
     */
    OwnerDto.OwnerSegmentEnum ownerSegment(Owner owner) {
        String tier = membershipLevel(owner) >= 3 ? "PREMIUM" : "STANDARD";
        boolean knownRegion = cityRegionResolver.timezoneForRegion(locality(owner)) != null;
        String area = knownRegion ? "METRO" : "REGIONAL";
        return OwnerDto.OwnerSegmentEnum.fromValue(tier + "_" + area);
    }

    /**
     * The owner's IANA timezone name derived from the owner's {@link #locality(Owner) locality}
     * via the fixed region-to-timezone table (NSW -> Australia/Sydney, VIC -> Australia/Melbourne,
     * QLD -> Australia/Brisbane). Returns null when the locality is not a region in the table.
     */
    String timezone(Owner owner) {
        return cityRegionResolver.timezoneForRegion(locality(owner));
    }

    /**
     * The owner's membership points: starting at 0, plus 2 when an email address is present,
     * plus 1 when namesakeCount is 0, plus 2 for a household of 3 or more members, plus 3 when
     * the owner's tenure is more than one fiscal year.
     */
    public int membershipPoints(Owner owner) {
        int points = 0;
        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
        if (hasEmail) {
            points += 2;
        }
        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
        if (uniqueName) {
            points += 1;
        }
        if (householdSize(owner) >= 3) {
            points += 2;
        }
        LocalDate registrationDate = owner.getRegistrationDate();
        boolean tenured = registrationDate != null
            && fiscalYear(LocalDate.now()) - fiscalYear(registrationDate) > 1;
        if (tenured) {
            points += 3;
        }
        return points;
    }

    /**
     * The owner's numeric membership level from 1 to 4, derived from {@link #membershipPoints}
     * via {@link #levelForPoints} and then held to the household level-ceiling by
     * {@link #cappedByHousehold}.
     */
    public int membershipLevel(Owner owner) {
        return cappedByHousehold(owner, levelForPoints(membershipPoints(owner)));
    }

    /**
     * Hold {@code level} to the household level-ceiling: an owner's membershipLevel may not exceed
     * one above the current maximum membershipLevel among the household members that already
     * existed when this owner registered — the other, non-deleted owners sharing its householdId
     * that were created earlier (a strictly lower id, ids being monotonic). When no such earlier
     * household member exists no ceiling applies and {@code level} is returned unchanged.
     *
     * @param owner the owner whose own level is being capped
     * @param level the owner's uncapped membership level
     * @return the level, capped at one above the earlier household members' maximum
     */
    private int cappedByHousehold(Owner owner, int level) {
        Integer id = owner.getId();
